hobbies = {"독서", "코딩"}
print("독서" in hobbies)
print("운동" not in hobbies)
for hobby in sorted(hobbies):
    print(hobby)

morning = {"민서", "지우"}
evening = {"지우", "하린"}
print(sorted(morning & evening))
print(sorted(morning | evening))
print(sorted(morning - evening))
print(sorted(evening - morning))

reading = {"민서", "지우"}
coding = {"지우", "도윤"}
print(sorted(reading & coding))
print(sorted(reading | coding))
print(sorted(reading - coding))
